// The script that protects the offline guarantee has to be shown to fail when
// it should, and to stay quiet when it should not.
@TestOn('mac-os || linux')
library;

import 'dart:io';

import 'package:flutter_test/flutter_test.dart';

final _script = '${Directory.current.path}/tool/check_offline.sh';

const _wifiTransport = 'lib/obd/transport/wifi_transport.dart';

const _lockfile = '''
# Generated by pub
packages:
  async:
    dependency: transitive
    description:
      name: async
      url: "https://pub.dev"
    source: hosted
    version: "2.13.0"
sdks:
  dart: ">=3.12.0 <4.0.0"
''';

String _lockWith(String package) =>
    '''
$_lockfile
  $package:
    dependency: transitive
    description:
      name: $package
      url: "https://pub.dev"
    source: hosted
    version: "1.0.0"
''';

String _manifest(String permissions) =>
    '''
<manifest xmlns:android="http://schemas.android.com/apk/res/android"
    xmlns:tools="http://schemas.android.com/tools">
$permissions
    <application android:label="TapeDash" />
</manifest>
''';

/// A throwaway project directory that starts out clean.
class _Project {
  _Project()
    : dir = Directory.systemTemp.createTempSync('tapedash_offline_test_') {
    write('pubspec.lock', _lockfile);
    write('lib/main.dart', 'void main() {}\n');
    write('android/app/src/main/AndroidManifest.xml', _manifest(''));
    addTearDown(() => dir.deleteSync(recursive: true));
  }

  final Directory dir;

  void write(String path, String content) {
    final file = File('${dir.path}/$path');
    file.parent.createSync(recursive: true);
    file.writeAsStringSync(content);
  }

  void permissions(String xml) =>
      write('android/app/src/main/AndroidManifest.xml', _manifest(xml));

  Future<ProcessResult> run([List<String> args = const ['--skip-gradle']]) =>
      Process.run('bash', [_script, '--root', dir.path, ...args]);
}

// `this.` matters here: a bare `stderr` would be dart:io's global.
extension on ProcessResult {
  String get err => this.stderr as String;
  String get out => this.stdout as String;
}

void main() {
  test('a clean project passes', () async {
    final result = await _Project().run();

    expect(result.exitCode, 0, reason: result.err);
    expect(result.out, contains('Offline check passed.'));
  });

  test('this repository passes', () async {
    final result = await Process.run('bash', [_script, '--skip-gradle']);

    expect(result.exitCode, 0, reason: result.err);
  });

  test('unknown options are rejected', () async {
    final result = await _Project().run(['--nope']);

    expect(result.exitCode, 2);
    expect(result.err, contains('unknown option'));
  });

  group('pubspec.lock', () {
    for (final package in [
      'http',
      'dio',
      'google_fonts',
      'url_launcher',
      'url_launcher_android',
      'firebase_core',
      'firebase_analytics',
      'flutter_analytics',
      'sentry',
      'sentry_flutter',
      'google_mobile_ads',
    ]) {
      test('rejects $package', () async {
        final project = _Project()..write('pubspec.lock', _lockWith(package));

        final result = await project.run();

        expect(result.exitCode, 1);
        expect(result.err, contains("banned package '$package'"));
      });
    }

    for (final package in ['http_parser', 'httpx_free', 'analytics_free']) {
      test('does not confuse $package with a banned one', () async {
        final project = _Project()..write('pubspec.lock', _lockWith(package));

        final result = await project.run();

        expect(result.exitCode, 0, reason: result.err);
      });
    }

    test('must exist', () async {
      final project = _Project();
      File('${project.dir.path}/pubspec.lock').deleteSync();

      final result = await project.run();

      expect(result.exitCode, 1);
      expect(result.err, contains('pubspec.lock is missing'));
    });
  });

  group('Dart sources', () {
    final violations = {
      'a banned package import': "import 'package:http/http.dart' as http;",
      'the dio import': 'import "package:dio/dio.dart";',
      'HttpClient': 'final c = HttpClient();',
      'Image.network': 'final w = Image.network(url);',
      'NetworkImage': 'final i = NetworkImage(url);',
      'launchUrl': 'await launchUrl(uri);',
      'a socket outside the WiFi transport':
          'final s = await Socket.connect(h, p);',
      'a WebSocket': 'final s = WebSocket.connect(u);',
      'a server socket': 'final s = ServerSocket.bind(h, p);',
      'a raw datagram socket': 'final s = RawDatagramSocket.bind(h, p);',
    };
    violations.forEach((name, code) {
      test('rejects $name', () async {
        final project = _Project()..write('lib/feature/thing.dart', '$code\n');

        final result = await project.run();

        expect(result.exitCode, 1);
        expect(result.err, contains('lib/feature/thing.dart:1'));
      });
    });

    test('allows sockets in the WiFi transport only', () async {
      final project = _Project()
        ..write(_wifiTransport, 'final s = await Socket.connect(h, p);\n');

      final result = await project.run();

      expect(result.exitCode, 0, reason: result.err);
    });

    test('still rejects an HTTP client in the WiFi transport', () async {
      final project = _Project()
        ..write(_wifiTransport, 'final c = HttpClient();\n');

      final result = await project.run();

      expect(result.exitCode, 1);
      expect(result.err, contains('$_wifiTransport:1'));
    });

    test('ignores comments and documentation', () async {
      final project = _Project()
        ..write('lib/feature/thing.dart', '''
// Never use HttpClient or Socket here.
/// Wraps a [Socket]; see package:http for why we do not use it.
void main() {} // Image.network is banned
''');

      final result = await project.run();

      expect(result.exitCode, 0, reason: result.err);
    });

    test('matches whole words only', () async {
      final project = _Project()
        ..write(
          'lib/feature/thing.dart',
          'class SimSocket {}\nclass MySocketHelper {}\nclass NetworkImageless {}\n',
        );

      final result = await project.run();

      expect(result.exitCode, 0, reason: result.err);
    });

    test('reports the line number', () async {
      final project = _Project()
        ..write(
          'lib/feature/thing.dart',
          'void a() {}\nvoid b() {}\nfinal c = HttpClient();\n',
        );

      final result = await project.run();

      expect(result.err, contains('lib/feature/thing.dart:3'));
    });
  });

  group('manifest permissions', () {
    for (final permission in [
      '<uses-permission android:name="android.permission.INTERNET" />',
      '<uses-permission android:name="android.permission.WAKE_LOCK" />',
      '<uses-permission android:name="android.permission.ACCESS_FINE_LOCATION" />',
      '<uses-permission android:name="android.permission.BLUETOOTH_CONNECT" />',
      '<uses-permission android:name="android.permission.BLUETOOTH" android:maxSdkVersion="30" />',
      '<uses-permission android:name="android.permission.BLUETOOTH_ADMIN" android:maxSdkVersion="30" />',
      '<uses-permission android:name="android.permission.BLUETOOTH_SCAN" android:usesPermissionFlags="neverForLocation" />',
      '<uses-permission android:name="io.github.ictashik.tapedash.DYNAMIC_RECEIVER_NOT_EXPORTED_PERMISSION" />',
      '<uses-permission android:name="android.permission.CAMERA" tools:node="remove" />',
    ]) {
      test('allows $permission', () async {
        final project = _Project()..permissions(permission);

        final result = await project.run();

        expect(result.exitCode, 0, reason: result.err);
      });
    }

    for (final permission in [
      '<uses-permission android:name="android.permission.CAMERA" />',
      '<uses-permission android:name="android.permission.READ_CONTACTS"/>',
      '<uses-permission android:name="android.permission.ACCESS_COARSE_LOCATION" />',
      '<uses-permission android:name="android.permission.ACCESS_NETWORK_STATE" />',
      '<uses-permission android:name="android.permission.RECORD_AUDIO" />',
      '<uses-permission-sdk-23 android:name="android.permission.READ_SMS" />',
      '<uses-permission\n        android:name="android.permission.CAMERA"\n        android:required="false" />',
      '<uses-permission android:name="com.google.android.gms.permission.AD_ID" />',
    ]) {
      test('rejects ${permission.replaceAll('\n', ' ')}', () async {
        final project = _Project()..permissions(permission);

        final result = await project.run();

        expect(result.exitCode, 1);
        expect(result.err, contains('not on the allowed list'));
      });
    }

    test('requires maxSdkVersion 30 on legacy Bluetooth permissions', () async {
      for (final name in ['BLUETOOTH', 'BLUETOOTH_ADMIN']) {
        final project = _Project()
          ..permissions(
            '<uses-permission android:name="android.permission.$name" />',
          );

        final result = await project.run();

        expect(result.exitCode, 1, reason: name);
        expect(
          result.err,
          contains('$name must set android:maxSdkVersion="30"'),
        );
      }
    });

    test('requires neverForLocation on BLUETOOTH_SCAN', () async {
      final project = _Project()
        ..permissions(
          '<uses-permission android:name="android.permission.BLUETOOTH_SCAN" />',
        );

      final result = await project.run();

      expect(result.exitCode, 1);
      expect(result.err, contains('neverForLocation'));
    });

    test('checks the merged release manifest as well as the source', () async {
      final project = _Project()
        ..write(
          'build/app/intermediates/merged_manifests/release/processReleaseManifest/arm64-v8a/AndroidManifest.xml',
          _manifest(
            '<uses-permission android:name="android.permission.CAMERA" />',
          ),
        );

      final result = await project.run();

      expect(result.exitCode, 1);
      expect(result.err, contains('merged_manifests/release'));
      expect(result.err, contains('android.permission.CAMERA'));
    });

    test('ignores debug and profile manifests, which add INTERNET', () async {
      final project = _Project()
        ..write(
          'build/app/intermediates/merged_manifest/debug/processDebugMainManifest/AndroidManifest.xml',
          _manifest(
            '<uses-permission android:name="android.permission.CAMERA" />',
          ),
        );

      final result = await project.run();

      expect(result.exitCode, 0, reason: result.err);
    });

    test('--strict requires a merged release manifest', () async {
      final result = await _Project().run(['--strict', '--skip-gradle']);

      expect(result.exitCode, 1);
      expect(result.err, contains('no merged release manifest'));
    });

    test('--strict passes with a clean merged release manifest', () async {
      final project = _Project()
        ..write(
          'build/app/intermediates/merged_manifest/release/processReleaseMainManifest/AndroidManifest.xml',
          _manifest(
            '<uses-permission android:name="android.permission.INTERNET" />',
          ),
        );

      final result = await project.run(['--strict', '--skip-gradle']);

      expect(result.exitCode, 0, reason: result.err);
    });
  });
}
